#include "atax.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Array initialization translated to Halide
// -----------------------------------------------------------------------------
static void init_array(int m, int n,
                       Halide::Buffer<num_t, 2> A,  // shape: [n, m]  (j, i)
                       Halide::Buffer<num_t, 1> x)  // shape: [n]     (j)
{
    // C layout:
    //   A[i][j] with i in [0..m-1], j in [0..n-1]
    //   x[j]     with j in [0..n-1]
    //
    // Halide layout (rule 1: first dimension is fastest-varying):
    //   A(j, i) with Buffer shape (n, m)
    //   x(j)    with Buffer shape (n)

    Var i("i"), j("j");

    Func init_A("init_A"), init_x("init_x");

    // fn = (DATA_TYPE)n;
    Expr fn = cast<num_t>(Expr(n));

    // -------------------------------------------------------------------------
    // x initialization
    //
    // for (i = 0; i < n; i++)
    //     x[i] = 1 + (i / fn);
    //
    // Here: x(j) = 1 + j / fn
    // -------------------------------------------------------------------------
    {
        Expr one = cast<num_t>(Expr(1));
        Expr j_f = cast<num_t>(j);
        init_x(j) = one + j_f / fn;
    }

    // -------------------------------------------------------------------------
    // A initialization
    //
    // for (i = 0; i < m; i++)
    //   for (j = 0; j < n; j++)
    //     A[i][j] = (DATA_TYPE)((i + j) % n) / (5*m);
    //
    // With A(j,i) layout:
    //   A(j,i) = ((i + j) % n) / (5*m)
    // -------------------------------------------------------------------------
    {
        Expr num   = cast<num_t>((i + j) % n);
        Expr denom = Expr(5 * m);  // promoted to num_t in the division
        init_A(j, i) = num / denom;
    }

    // -------------------------------------------------------------------------
    // Simple schedule for initialization
    //
    // We vectorize over the innermost (contiguous) dimension j,
    // and parallelize over the outer dimension i for A.
    // -------------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = natural_vector_size<num_t>(target);

    // x is 1D over j: vectorize and (for large n) parallelize
    init_x
        .vectorize(j, vec_width)
        .parallel(j, 1024);  // coarse-grain parallelism over chunks of j

    // A(j,i): j is contiguous, i is outer; parallelize rows (i), vectorize cols (j)
    init_A
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize into the provided Buffers
    init_x.realize(x);
    init_A.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size (from atax.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Buffers:
    // A(i,j) in C becomes A(j,i) with shape (n, m) in Halide.
    Halide::Buffer<num_t, 2> A(n, m);  // [j, i]
    Halide::Buffer<num_t, 1> x(n);     // [j]
    Halide::Buffer<num_t, 1> y(n);     // [j] output

    // Initialize data
    init_array(m, n, A, x);

    // Wrap A and x as ImageParams so the pipeline is decoupled from
    // the concrete Buffers and can be JIT-compiled independently.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Vars and reduction domains
    Var i("i"), j("j");
    // Use the runtime extents of A to define the reduction ranges,
    // mirroring the original C loops over N and M.
    RDom r1(0, A.dim(0).extent(), "r1");  // corresponds to j in [0..n-1]
    RDom r2(0, A.dim(1).extent(), "r2");  // corresponds to i in [0..m-1]

    // -------------------------------------------------------------------------
    // Kernel translation
    //
    // Original C kernel:
    //
    //   for (i = 0; i < _PB_N; i++)
    //     y[i] = 0;
    //   for (i = 0; i < _PB_M; i++) {
    //     tmp[i] = 0;
    //     for (j = 0; j < _PB_N; j++)
    //       tmp[i] = tmp[i] + A[i][j] * x[j];
    //     for (j = 0; j < _PB_N; j++)
    //       y[j] = y[j] + A[i][j] * tmp[i];
    //   }
    //
    // This is:
    //   tmp[i] = sum_j A[i][j] * x[j];
    //   y[j]   = sum_i A[i][j] * tmp[i];
    //
    // With our layout A(j,i):
    //   tmp(i) = sum_j A(j,i) * x(j);
    //   y(j)   = sum_i A(j,i) * tmp(i);
    // -------------------------------------------------------------------------
    Func tmp("tmp"), y_func("y_func");

    // tmp(i) = sum over r1 (j) of A(j,i) * x(j)
    tmp(i) = cast<num_t>(Expr(0));
    tmp(i) += A_param(r1, i) * x_param(r1);

    // y(j) = sum over r2 (i) of A(j,i) * tmp(i)
    y_func(j) = cast<num_t>(Expr(0));
    y_func(j) += A_param(j, r2) * tmp(r2);

    // -------------------------------------------------------------------------
    // Schedule
    //
    // Goals:
    //   - Preserve original semantics (two-phase ATAX: tmp then y).
    //   - Parallelize across independent rows/columns.
    //   - Vectorize along the contiguous dimension (j).
    //   - Keep memory access patterns streaming and cache-friendly.
    // -------------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = natural_vector_size<num_t>(target);

    // Tunable tile size for splitting the y(j) loop. Must be a multiple
    // of vec_width for clean vectorization; can be adjusted to match
    // cache characteristics of the machine.
    const int tile_j = vec_width * 32;  // e.g. AVX2 float: 8*32 = 256

    Var jo("jo"), ji("ji");

    // 1) Compute tmp once in full, like the first nested loop in the C code:
    //
    //    for (i = 0; i < M; i++) {
    //      tmp[i] = 0;
    //      for (j = 0; j < N; j++)
    //        tmp[i] += A[i][j] * x[j];
    //    }
    //
    //    We parallelize across 'i' because each dot product is independent.
    tmp
        .compute_root()
        .parallel(i);

    // 2) Compute y at the root as well. We split and schedule both the
    //    pure definition (initial y(j)=0) and the update (reduction over i).
    //
    //    Pure step: y(j) = 0;
    y_func
        .compute_root()
        // Split j so we can parallelize outer tiles and vectorize inner lanes
        .split(j, jo, ji, tile_j)
        .parallel(jo)
        .vectorize(ji, vec_width);

    //    Update step:
    //      for (i = 0; i < M; i++)
    //        for (j = 0; j < N; j++)
    //          y[j] += A[i][j] * tmp[i];
    //
    //    We schedule this as:
    //      for (jo in tiles of j)    // parallel
    //        for (i = 0..M-1)
    //          for (ji in vector lanes) // vectorized j
    //
    //    This keeps j (the contiguous dimension) innermost and vectorized,
    //    and parallelizes independent ranges of j across cores.
    y_func.update()
        .split(j, jo, ji, tile_j)
        // Inner-to-outer order: ji (vectorized j), r2 (i), jo (tile index)
        .reorder(ji, r2, jo)
        .parallel(jo)
        .vectorize(ji, vec_width);

    // -------------------------------------------------------------------------
    // Bind actual Buffers to the ImageParams
    // -------------------------------------------------------------------------
    A_param.set(A);
    x_param.set(x);

    // JIT-compile the kernel with the chosen target
    y_func.compile_jit(target);

    // -------------------------------------------------------------------------
    // Run and time the kernel
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize y_func into y buffer
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Print results (to prevent dead-code elimination and for checking)
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print execution time in seconds (like gemm.cpp)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
